import { describe, expect, it, vi } from 'vitest'

const messages = {
  getLatest: () => 'welcome',
}

describe('messages', () => {
  it('observes and overrides a method', () => {
    const spy = vi.spyOn(messages, 'getLatest')
      .mockImplementationOnce(() => 'access-restricted')

    expect(messages.getLatest()).toBe('access-restricted')
    expect(spy).toHaveBeenCalledOnce()

    spy.mockRestore()
    expect(messages.getLatest()).toBe('welcome')
  })

  it('passes a mock as a callback', () => {
    const callback = vi.fn()
    callback('saved')
    expect(callback).toHaveBeenCalledWith('saved')
  })
})

