import { afterEach, beforeEach, describe, expect, test } from 'vitest'

const events: string[] = []

beforeEach(() => events.push('outer before'))
afterEach(() => events.push('outer after'))

describe('nested suite', () => {
  beforeEach(() => events.push('inner before'))
  afterEach(() => events.push('inner after'))

  test('runs hooks hierarchically', () => {
    events.push('test')
    expect(events).toEqual(['outer before', 'inner before', 'test'])
  })
})

test('cleanup order', () => {
  expect(events.slice(-2)).toEqual(['inner after', 'outer after'])
})

