import { expect } from 'vitest'

expect.extend({
  toBeWithinRange(received: number, min: number, max: number) {
    const pass = received >= min && received <= max
    return {
      pass,
      message: () => `expected ${received} to be within ${min} and ${max}`,
    }
  },
})
